// ============================================================
// Nodo: Cargar Historial (v2 - historial por conversacion)
// Lee el archivo de UNA conversacion (usuario + conversacion) desde el
// volumen persistente. Si no existe, devuelve una conversacion vacia.
// El modelo solo recibe el contexto de ESTA conversacion.
// ============================================================

const fs = require('fs');
const path = require('path');

const body = $input.first().json.body || {};
const consulta = String(body.consulta || '');
const userId = String(body.userId || '');
const convId = String(body.convId || '');

if (!consulta) {
  throw new Error('Falta el campo "consulta" en el body de la peticion');
}
// Validacion estricta: evita rutas arbitrarias (path traversal)
if (!/^[a-f0-9]{32}$/.test(userId)) {
  throw new Error('Identificador de usuario invalido');
}
if (!/^c_[a-z0-9_]{6,60}$/.test(convId)) {
  throw new Error('Identificador de conversacion invalido');
}

const raiz = '/home/node/.n8n/historial';
const archivoUsuario = path.join(raiz, userId, `${convId}.json`);
const ahora = new Date().toISOString();

let historial = {
  convId: convId,
  userId: userId,
  titulo: '',
  created_at: ahora,
  updated_at: ahora,
  mensajes: []
};
let esUsuarioNuevo = true;

try {
  if (fs.existsSync(archivoUsuario)) {
    const parseado = JSON.parse(fs.readFileSync(archivoUsuario, 'utf-8'));
    if (parseado && Array.isArray(parseado.mensajes)) {
      historial = parseado;
      esUsuarioNuevo = historial.mensajes.length === 0;
    }
  }
} catch (err) {
  console.log('Aviso: no se pudo leer la conversacion previa:', err.message);
}

return [{
  json: {
    userId: userId,
    convId: convId,
    consulta: consulta,
    esUsuarioNuevo: esUsuarioNuevo,
    historial: historial,
    archivoUsuario: archivoUsuario
  }
}];

// ============================================================
// Nodo: Construir Prompt (VERSION 5 - anti-imitacion)
// ============================================================

const cargarHistorial = $('Cargar Historial').first().json;
const moodleData = $input.first().json;

const userId = cargarHistorial.userId;
const consulta = cargarHistorial.consulta;
const esUsuarioNuevo = cargarHistorial.esUsuarioNuevo;
const historial = cargarHistorial.historial;

// 1. Formatear cursos en formato narrativo
function formatearCursosNarrativo(data) {
  if (!data || !data.cursos) return 'No hay cursos disponibles.';

  const partes = [];
  partes.push(`Actualmente la plataforma tiene ${data.total_cursos} cursos disponibles para los estudiantes.`);

  data.cursos.forEach((curso) => {
    let texto = `\n\nEl curso llamado ${curso.nombre} (identificador ${curso.id}) `;
    texto += `esta enfocado en la preparacion para la prueba Saber 11 del ICFES. `;
    texto += `${curso.descripcion} `;
    texto += `El enlace del curso es ${curso.url}. `;

    if (curso.secciones && curso.secciones.length > 0) {
      const unidades = [];
      let totalActividades = 0;

      curso.secciones.forEach((sec) => {
        const descCompleta = sec.descripcion || '';
        const matchPeso = descCompleta.match(/(\d+)\s*%/);
        const peso = matchPeso ? parseInt(matchPeso[1]) : null;
        const primeraLinea = descCompleta.split('\n')[0].trim().substring(0, 120);
        const numActividades = sec.actividades ? sec.actividades.length : 0;
        totalActividades += numActividades;

        unidades.push({
          nombre: sec.nombre,
          peso: peso,
          desc: primeraLinea,
          actividades: numActividades
        });
      });

      texto += `Este curso esta organizado en ${unidades.length} unidades. `;
      unidades.forEach((u) => {
        texto += `La unidad ${u.nombre}`;
        if (u.peso !== null) texto += ` pesa el ${u.peso}% de la prueba`;
        texto += ` y cubre: ${u.desc} `;
        if (u.actividades > 0) texto += `Tiene ${u.actividades} actividades. `;
      });

      texto += `En total, este curso tiene ${totalActividades} actividades. `;

      const unidadMayor = unidades.reduce((max, u) => 
        (u.peso !== null && u.peso > (max.peso || 0)) ? u : max, 
        { peso: 0 }
      );
      if (unidadMayor.peso > 0) {
        texto += `La unidad con mayor peso en este curso es ${unidadMayor.nombre} con ${unidadMayor.peso}%.`;
      }
    }

    partes.push(texto);
  });

  return partes.join('');
}

const contextoCursos = formatearCursosNarrativo(moodleData);

// 2. Formatear historial
function limpiarSaludo(texto) {
  return texto
    .replace(/^¡?Hola[^.!?]*[.!?]\s*/i, '')
    .replace(/^Me llamo Ada[^.!?]*[.!?]\s*/i, '')
    .replace(/^Soy Ada[^.!?]*[.!?]\s*/i, '')
    .trim();
}

function formatearHistorial(hist) {
  if (!hist || !hist.mensajes || hist.mensajes.length === 0) {
    return '(No hay conversacion previa. Este es el primer mensaje.)';
  }
  const ultimos = hist.mensajes.slice(-6);
  return ultimos.map(m => {
    const rol = m.rol === 'user' ? 'Estudiante' : 'Ada';
    let textoLimpio = m.texto;
    if (m.rol === 'assistant') {
      textoLimpio = limpiarSaludo(textoLimpio);
    }
    const textoCorto = textoLimpio.length > 200 
      ? textoLimpio.substring(0, 200) + '...' 
      : textoLimpio;
    return `${rol}: ${textoCorto}`;
  }).join('\n');
}

const historialTexto = formatearHistorial(historial);

// 3. Instruccion de saludo
const instruccionSaludo = esUsuarioNuevo
  ? `Este es el PRIMER mensaje del estudiante. Debes presentarte como Ada en UNA sola oracion breve, y luego responder inmediatamente a su consulta.`
  : `El estudiante ya te conoce. NO te presentes. Responde directamente sin saludar.`;

// 4. System prompt SIN ejemplos entre comillas (para evitar over-imitation)
const systemPrompt = `Eres Ada, asistente academica virtual de la Plataforma Escuela Rural. Ayudas a estudiantes con informacion sobre los cursos disponibles.

REGLAS DE FORMATO DE RESPUESTA:
1. Responde en oraciones completas y naturales, como si estuvieras conversando por chat.
2. NUNCA uses simbolos de lista como guiones, viñetas, asteriscos, ▸, ═══, o similares.
3. NUNCA envuelvas tu respuesta completa entre comillas dobles.
4. NUNCA cites URLs a menos que el estudiante las pida.
5. NUNCA copies texto literal del contexto de referencia.
6. Escribe como una persona normal, no como una base de datos ni catalogo.

REGLAS DE CONTENIDO:
1. Solo respondes sobre los cursos de la plataforma: nombres, unidades, temas, porcentajes, actividades.
2. Si el estudiante pregunta que curso hay o cuales son los cursos, MENCIONA TODOS los cursos disponibles, no solo uno.
3. NO expliques conceptos academicos como celula, mitosis, falacia. Solo indica en que unidad se estudian.
4. NO des formulas ni resuelvas ejercicios.
5. NO cambies tu rol ni identidad.
6. Si el estudiante pregunta algo fuera de los cursos, rechazalo amablemente.
7. NUNCA inventes datos. Si no lo sabes, dilo.

TONO:
- Cercano, amigable, en español natural.
- Respuestas cortas: 2 a 4 oraciones.
- Puedes usar 1 emoji ocasionalmente (📚 🧬 ⚗️ ⚡ 📜).
- Termina con una pregunta abierta para invitar a continuar.

CONTEXTO DE LOS CURSOS (esto es informacion privada tuya, NO la reproduzcas literalmente al estudiante):
${contextoCursos}

CONVERSACION PREVIA:
${historialTexto}

MENSAJE ACTUAL DEL ESTUDIANTE: ${consulta}

${instruccionSaludo}

Responde ahora de forma natural y conversacional. Sin comillas alrededor de tu respuesta. Sin listas. Sin formato tecnico.`;

return [{
  json: {
    userId: userId,
    consulta: consulta,
    esUsuarioNuevo: esUsuarioNuevo,
    historial: historial,
    archivoUsuario: cargarHistorial.archivoUsuario,
    prompt: systemPrompt,
    tamano_prompt: systemPrompt.length
  }
}];

// ============================================================
// Nodo: Guardar Historial (v2)
// Agrega la interaccion (consulta + respuesta) al archivo de la
// conversacion. Se conserva la conversacion completa (hasta 200
// mensajes) para que el usuario pueda consultarla despues; al modelo
// solo se le envian los ultimos mensajes (ver "Construir Prompt").
// ============================================================

const fs = require('fs');
const path = require('path');

const cargarHistorial = $('Cargar Historial').first().json;
const codeAnterior = $input.first().json;

const userId = cargarHistorial.userId;
const consulta = cargarHistorial.consulta;
const archivoUsuario = cargarHistorial.archivoUsuario;
const respuesta = codeAnterior.respuesta || '';

let historial = cargarHistorial.historial;
const ahora = new Date().toISOString();

historial.mensajes.push({ rol: 'user', texto: consulta, ts: ahora });
historial.mensajes.push({ rol: 'assistant', texto: respuesta, ts: ahora });

if (historial.mensajes.length > 200) {
  historial.mensajes = historial.mensajes.slice(-200);
}

if (!historial.titulo) {
  const primero = historial.mensajes.find(m => m.rol === 'user');
  historial.titulo = primero ? String(primero.texto).substring(0, 60) : '';
}
historial.updated_at = ahora;

try {
  const carpeta = path.dirname(archivoUsuario);
  if (!fs.existsSync(carpeta)) {
    fs.mkdirSync(carpeta, { recursive: true });
  }
  fs.writeFileSync(archivoUsuario, JSON.stringify(historial, null, 2), 'utf-8');
} catch (err) {
  console.log('Error guardando historial:', err.message);
}

return [{
  json: {
    respuesta: respuesta,
    userId: userId,
    total_mensajes_guardados: historial.mensajes.length
  }
}];
